extends Node

var questions: Array[Dictionary] = [
	{
		"question": "Quale pianeta del sistema solare è noto come il Pianeta Rosso?",
		"options": ["Venere", "Marte", "Giove", "Saturno"],
		"correct": 1
	},
	{
		"question": "Qual è il linguaggio di scripting nativo di Godot?",
		"options": ["GDScript", "Python", "Lua", "C#"],
		"correct": 0
	},
	{
		"question": "Quanti bit formano un singolo byte?",
		"options": ["4", "8", "16", "32"],
		"correct": 1
	}
]

var score: int = 0
var high_score: int = 0

extends Control

@onready var score_label: Label = $CenterContainer/VBoxContainer/ScoreLabel
@onready var high_score_label: Label = $CenterContainer/VBoxContainer/HighScoreLabel
@onready var restart_button: Button = $CenterContainer/VBoxContainer/ButtonsContainer/RestartButton
@onready var menu_button: Button = $CenterContainer/VBoxContainer/ButtonsContainer/MenuButton


func _ready() -> void:
	score_label.text = "Punteggio: " + str(QuizData.score)
	high_score_label.text = "Record: " + str(QuizData.high_score)
	restart_button.grab_focus()
	restart_button.pressed.connect(_on_restart_button_pressed)
	menu_button.pressed.connect(_on_menu_button_pressed)


func _on_restart_button_pressed() -> void:
	get_tree().change_scene_to_file("res://quiz.tscn")


func _on_menu_button_pressed() -> void:
	get_tree().change_scene_to_file("res://menu.tscn")

extends Control

